  unicode-range: U+0020-007F;
}

@font-face {
  font-family: 'InterVar';
  src: url('inter.var.woff2') format('woff2-variations');
  font-weight: 100 900;
}
.bold { font-weight: 650; }

body {
  font-family: 'Raleway', Arial, sans-serif;
  font-size-adjust: 0.5;
}

h1 {
  text-box-trim: both;
  text-box-edge: cap alphabetic;
}

.btn:focus-visible {
  outline: 3px solid currentColor;
  outline-offset: 4px;
}

const range = document.createRange();
range.setStart(textNode, 5);
range.setEnd(textNode, 10);

const highlight = new Highlight(range);
CSS.highlights.set('search', highlight);

.tooltip {
  position: absolute;
  position-anchor: --trigger;
  top: anchor(bottom);
  left: anchor(center);
  translate: -50% 0;
}

.orbit {
  --angle: 0deg;
  transform:
    translate(
      calc(100px * cos(var(--angle))),
      calc(100px * sin(var(--angle)))
    );
}

.card {
  &:is(:hover, :focus-within) {
    box-shadow: 0 8px 24px rgba(0,0,0,.15);
    transform: translateY(-2px);
  }
}

@scope (.card) {
  :scope { border-radius: 8px; }
  .title { font-weight: bold; }
  img { width: 100%; aspect-ratio: 16/9; object-fit: cover; }
}

:target {
  scroll-margin-top: 80px;
}

.card {
  border-inline-start: 4px solid var(--brand);
  padding-inline: 16px;
}

/* Proposed: auto-select readable color against background */
.btn {
  background: var(--brand);
  color: color-contrast(var(--brand) vs black, white);
}

.avatar {
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
}
/* vs */
